arguments.argument:
if(mouse_samples == -1)
{
    baseybegin = ybegin;
    mouse_samples = ds_list_create();
}
if(view_hview[0] < 600)
{
    ds_list_add(mouse_samples, window_mouse_get_y());
    while(ds_list_size(mouse_samples) > 10)
        ds_list_delete(mouse_samples, 0);
    var des_y;
    des_y = 0;
    for(i = 0; i < ds_list_size(mouse_samples); i += 1)
        des_y += ds_list_find_value(mouse_samples, i);
    des_y /= ds_list_size(mouse_samples);

    ybegin = round(baseybegin
                   - min(1, max(0, des_y/view_hview[0]))
                     *(600-view_hview[0]));
}
stepHasRun = true;

var itemcount;
menu_hack_backbutton();
itemcount = menu_get_itemcount();

if(editing != -1) {
    // TODO(enigma): if/else instead of switch; ENIGMA can't switch on strings. Restore switch when fixed
    var editingType;
    editingType = item_type[editing];
    if (editingType == "edittext2" or editingType == "edittext" or editingType == "editnum") {
        if (keyboard_check(vk_control) && keyboard_check(ord("V"))) {
            keyboard_string += clipboard_get_text();
            keyboard_clear(ord("V"));
        }
        item_value[editing] = keyboard_string;
    }
    else if (editingType == "editkeyormouse" or editingType == "editkey") {
        // editkeyormouse checks the mouse first, then falls through to the key check
        if (editingType == "editkeyormouse") {
            if mouse_check_button(mb_left) {
                menu_set_var(editing, MOUSE_LEFT);
                run_action(item_script[editing], MOUSE_LEFT);
                editing = -1;
                exit;
            }
            else if mouse_check_button(mb_right) {
                menu_set_var(editing, MOUSE_RIGHT);
                run_action(item_script[editing], MOUSE_RIGHT);
                editing = -1;
                exit;
            }
        }
        if keyboard_check_direct(vk_tab) keyboard_lastkey = vk_tab;
        if keyboard_lastkey != 0 {
            menu_set_var(editing, keyboard_lastkey);
            run_action(item_script[editing], menu_get_var(editing));
            editing = -1;
            exit;
        }
    }
} else if(mouse_x > view_xview[0]+xbegin) {
    if(mouse_y >= view_yview[0]+ybegin-(spacing/2) and mouse_x < view_xview[0]+xbegin+width)
    {
        virtualitem = max(0, round((mouse_y-(view_yview[0]+ybegin))/spacing));
        if(mouse_check_button_pressed(mb_left)){
            mouse_clear(mb_left);
            if(virtualitem < itemcount) {
                // TODO(enigma): if/else instead of switch; ENIGMA can't switch on strings. Restore switch when fixed
                var clickedType;
                clickedType = item_type[virtualitem];
                if (clickedType == "script")
                    run_action(item_script[virtualitem], 0);
                else if (clickedType == "editscript")
                    item_value[virtualitem] = run_action(item_script[virtualitem], 0);
                else if (clickedType == "editkey" or clickedType == "editkeyormouse") {
                    io_clear();
                    editing = virtualitem;
                }
                else if (clickedType == "edittext" or clickedType == "edittext2" or clickedType == "editnum") {
                    keyboard_string = "";
                    editing = virtualitem;
                }
                else if (clickedType == "editselect") {
                    item_value[virtualitem] = (item_value[virtualitem]+1) mod item_options[virtualitem];
                    menu_set_var(virtualitem, item_option_value[virtualitem, item_value[virtualitem]]);
                    run_action(item_script[virtualitem], menu_get_var(virtualitem));
                }
            }
        }
    }
    else if(mouse_y < view_yview[0]+ybegin-taboffset+spacing/2 and mouse_y > view_yview[0]+ybegin-taboffset-spacing/2
            and mouse_x > view_xview[0]+xbegin+tabmargin and mouse_x < view_xview[0]+xbegin+tabmargin+tabspacing*tabs)
    {
        virtualitem = min(-2, -2-floor((mouse_x-(view_xview[0]+xbegin+tabmargin))/tabspacing));
        if(mouse_check_button_pressed(mb_left))
        {
            mouse_clear(mb_left);
            if(-2-virtualitem < tabs)
            {
                run_action(tab_script[-2-virtualitem], 0);
            }
        }
    } else {
        virtualitem = -1;
    }
} else {
    virtualitem = -1;
}
